    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, '201: What is the most appropriate next step for a pregnant woman who has a positive result on a cystic fibrosis carrier screen?', '["Immediate amniocentesis", "Testing of the biological father for carrier status", "Testing the fetus with CVS", "Reassurance"]', 1, 'If both parents are carriers, there is a 25% risk for the fetus. (ACOG)'),
    (v_topic_id, '202: At what gestational age is the risk of fetal injury from radiation (e.g., from an X-ray) the highest?', '["0-2 weeks (all-or-none period)", "2-8 weeks (organogenesis)", "20-24 weeks", "Third trimester"]', 1, 'The risk of malformations and microcephaly is highest during organogenesis. (Gabbe)'),
    (v_topic_id, '203: "Fetal Alcohol Spectrum Disorder" (FASD) is characterized by which of the following facial features?', '["Large jaw", "Smooth philtrum, thin upper lip, and short palpebral fissures", "Wide-set eyes (hypertelorism)", "Cleft palate"]', 1, 'Alcohol is a significant teratogen with no known safe level in pregnancy. (Williams)'),
    (v_topic_id, '204: Maternal "tobacco use" is most strongly associated with which of the following neonatal outcomes?', '["Congenital heart disease", "Low birth weight (IUGR)", "Limb reduction defects", "Neural tube defects"]', 1, 'Nicotine and carbon monoxide cause placental insufficiency. (ACOG)'),
    (v_topic_id, '205: Which of the following is a symptom of "Postpartum Depression" (PPD) that distinguishes it from "Postpartum Blues"?', '["Transient tearfulness", "Symptoms lasting > 2 weeks and interference with activities of daily living", "Fatigue", "Irritability"]', 1, 'Postpartum blues typically resolve within 10-14 days and do not include suicidal ideation. (Beckmann)'),
    (v_topic_id, '206: What is the most appropriate first-line pharmacotherapy for a breastfeeding woman with moderate to severe Postpartum Depression?', '["Estrogen replacement", "SSRIs (e.g., Sertraline or Paroxetine)", "Benzodiazepines", "St. John''s Wort"]', 1, 'Sertraline is often preferred due to low levels in breast milk. (ACOG)'),
    (v_topic_id, '207: "Postpartum Psychosis" is a medical emergency. What is the most important risk to assess?', '["Risk of weight gain", "Risk of infanticide or suicide", "Risk of milk supply failure", "Risk of infection"]', 1, 'Requires immediate hospitalization and psychiatric intervention. (Williams)'),
    (v_topic_id, '208: When can "ovulation" typically resume in a non-breastfeeding woman after delivery?', '["1 week", "3-4 weeks (earliest)", "6 months", "1 year"]', 1, 'Contraception should be discussed early. (Gabbe)'),
    (v_topic_id, '209: Which of the following is a preferred method of "contraception" for a woman who is breastfeeding and desires a hormonal option?', '["Combined oral contraceptives (estrogen + progestin)", "Progestin-only pills (Minipill)", "Copper IUD", "None of the above"]', 1, 'Estrogen can interfere with milk production; progestin-only methods are preferred. (ACOG)'),
    (v_topic_id, '210: "Lactational Amenorrhea Method" (LAM) for contraception is only reliable if:', '["The infant is < 6 months old", "Breastfeeding is exclusive (no formula)", "The mother is amenorrheic", "All of the above"]', 3, 'When these conditions are met, LAM is >98% effective. (Williams)'),
    (v_topic_id, '211: What is the standard duration of the "Postpartum Period" (Puerperium)?', '["2 weeks", "6 weeks", "3 months", "Until the first period"]', 1, 'The 6-week period during which the mother''s body returns to its pre-pregnant state. (Beckmann)'),
    (v_topic_id, '212: "Lochia Rubra" refers to postpartum vaginal discharge that is:', '["Bloody and lasts 3-4 days", "Pinkish-brown and lasts 1-2 weeks", "White or yellowish", "Foul-smelling"]', 0, 'Followed by lochia serosa and then lochia alba. (Gabbe)'),
    (v_topic_id, '213: A "fever" in the first 24 hours postpartum is often due to:', '["Endometritis", "Dehydration or normal physiologic response", "UTI", "Breast abscess"]', 1, 'True postpartum infection (morbidity) is defined as temp > 38C on 2 of the first 10 days, excluding the first 24h. (Williams)'),
    (v_topic_id, '214: What is the most common cause of "Postpartum Endometritis"?', '["Staphylococcus aureus", "Polymicrobial (anaerobes and aerobes from the vaginal flora)", "Group A Strep", "Chlamydia"]', 1, 'Risk is much higher after Cesarean section. (ACOG)'),
    (v_topic_id, '215: The classic treatment for postpartum endometritis is IV antibiotics consisting of:', '["Penicillin and Gentamicin", "Clindamycin and Gentamicin", "Vancomycin", "Ciprofloxacin"]', 1, 'Clindamycin provides good anaerobic coverage. (Gabbe)'),
    (v_topic_id, '216: A breastfeeding mother has a painful, red, warm area on one breast and a fever. Diagnosis?', '["Engorgement", "Mastitis", "Galactocele", "Inflammatory breast cancer"]', 1, 'Often caused by S. aureus entering through cracked nipples. (Beckmann)'),
    (v_topic_id, '217: What is the appropriate management for a woman with "Mastitis"?', '["Stop breastfeeding on the affected side", "Oral antibiotics (e.g., Dicloxacillin) and CONTINUE breastfeeding or pumping", "Aspiration of the area", "Strict NPO"]', 1, 'Emptying the breast is critical to prevent abscess formation. (ACOG)'),
    (v_topic_id, '218: "Breast Engorgement" typically occurs when?', '["Day 1-2", "Day 3-5 (when mature milk comes in)", "At 6 weeks", "After weaning"]', 1, 'Painful swelling due to increased blood flow and milk production. (Williams)'),
    (v_topic_id, '219: What is the primary recommendation for a mother who does NOT wish to breastfeed to manage engorgement?', '["Pumping the breast until empty", "Tight-fitting bra, ice packs, and avoidance of nipple stimulation", "Heat packs", "Drinking excessive fluids"]', 1, 'Nipple stimulation and emptying the breast will prolong milk production. (Gabbe)'),
    (v_topic_id, '220: Which of the following is an advantage of "Colostrum" (the early milk produced in the first few days)?', '["High in fat", "Rich in antibodies (IgA) and protein", "Low in calories", "High in lactose"]', 1, 'Provides essential passive immunity to the neonate. (Beckmann)'),
    (v_topic_id, '221: "Advanced Maternal Age" (AMA) is defined as pregnancy occurring at age:', '["30 years or older", "35 years or older at the time of delivery", "40 years or older", "45 years or older"]', 1, 'Associated with an increased risk of chromosomal abnormalities (e.g., Down syndrome). (ACOG)'),
    (v_topic_id, '222: At age 35, what is the approximate risk of having a child with Down Syndrome?', '["1 in 10", "1 in 385 (at delivery)", "1 in 1000", "1 in 2000"]', 1, 'The risk increases exponentially with age. (Williams)'),
    (v_topic_id, '223: Which of the following is a common cause of "leg cramps" in the third trimester?', '["Potassium deficiency", "Calcium/Magnesium imbalance and pressure from the uterus", "Blood clots", "Varicose veins"]', 1, 'Dorsiflexion of the foot usually relieves the cramp. (Gabbe)'),
    (v_topic_id, '224: "Round Ligament Pain" is typically described as:', '["Sharp, localized pain in the lower quadrants triggered by movement", "Dull backache", "Burning on urination", "Heavy pelvic pressure"]', 0, 'Due to stretching of the round ligaments as the uterus enlarges. (Beckmann)'),
    (v_topic_id, '225: What is the recommended treatment for "Carpal Tunnel Syndrome" in pregnancy?', '["Surgery", "Wrist splints at night", "NSAIDs", "Immediate delivery"]', 1, 'Often caused by edema-mediated compression of the median nerve. (ACOG)'),
    (v_topic_id, '226: Pregnant women are advised to avoid "soft cheeses" (like Brie, Camembert, Feta) because of the risk of:', '["Salmonella", "Listeria monocytogenes", "E. coli", "Campylobacter"]', 1, 'Listeriosis can cause miscarriage, stillbirth, or neonatal meningitis. (CDC)'),
    (v_topic_id, '227: Which fish should be strictly avoided in pregnancy due to high levels of "Methylmercury"?', '["Salmon", "Swordfish, King Mackerel, Shark, and Tilefish", "Canned light tuna", "Shrimp"]', 1, 'Limit other fish to 8-12 oz per week. (FDA/ACOG)'),
    (v_topic_id, '228: Why is "Iron" supplementation essential in pregnancy?', '["To prevent constipation", "To support the 50% increase in red blood cell mass and fetal requirements", "To prevent neural tube defects", "To induce labor"]', 1, 'Iron deficiency is the most common cause of anemia in pregnancy. (Williams)'),
    (v_topic_id, '229: Which of the following is a risk factor for "Abruptio Placentae"?', '["Hypertension", "Cocaine use", "Abdominal trauma", "All of the above"]', 3, 'Also includes previous abruption and smoking. (ACOG)'),
    (v_topic_id, '230: A "Kleihauer-Betke" test showing 1% fetal cells in maternal blood helps calculate the dose of:', '["Insulin", "RhoGAM", "Methotrexate", "Heparin"]', 1, '1% = 50 mL of fetal blood; requires multiple vials of RhoGAM. (Gabbe)'),
    (v_topic_id, '231: "Ectopic Pregnancy" should be suspected in any woman of reproductive age presenting with:', '["Nausea and vomiting", "Amenorrhea and abdominal pain", "High fever", "Increased appetite"]', 1, 'Always perform a pregnancy test (hCG) in these patients. (Beckmann)'),
    (v_topic_id, '232: In a hemodynamically unstable patient with a ruptured ectopic pregnancy, the treatment of choice is:', '["Methotrexate", "Emergent Laparoscopy or Laparotomy", "Dilation and Curettage", "Wait for hCG to drop"]', 1, 'Surgical control of hemorrhage is mandatory. (ACOG)'),
    (v_topic_id, '233: "Gestational Trophoblastic Neoplasia" (GTN) refers to:', '["Normal twin pregnancy", "Malignant transformation of a molar pregnancy (e.g., Choriocarcinoma)", "Placental abruption", "Polyhydramnios"]', 1, 'Characterized by persistent or rising hCG levels after evacuation. (Williams)'),
    (v_topic_id, '234: What is the primary site of metastasis for "Choriocarcinoma"?', '["Liver", "Brain", "Lungs", "Bones"]', 2, 'Presents as hemoptysis; very sensitive to chemotherapy (Methotrexate). (Gabbe)'),
    (v_topic_id, '235: "Hyperemesis Gravidarum" is often associated with which other obstetric condition?', '["Ectopic pregnancy", "Multiple gestation or Molar pregnancy", "Placenta previa", "Breech presentation"]', 1, 'Conditions with very high hCG levels. (Beckmann)'),
    (v_topic_id, '236: Which of the following is the most common cause of "Polyhydramnios"?', '["Fetal anomalies", "Gestational diabetes", "Idiopathic (unknown)", "Multiple gestation"]', 2, 'About 50-60% of cases have no identifiable cause. (Williams)'),
    (v_topic_id, '237: A "Cystic Hygroma" seen on 1st-trimester ultrasound is highly associated with:', '["Trisomy 21", "Turner Syndrome (45,X)", "Gestational diabetes", "Breech presentation"]', 1, 'A lymphatic malformation in the neck region. (Gabbe)'),
    (v_topic_id, '238: "Nuchal Translucency" (NT) measurement is part of screening for:', '["Neural tube defects", "Aneuploidy (e.g., Down syndrome)", "Skeletal deformities", "Gestational diabetes"]', 1, 'Increased NT (> 3mm) is an abnormal finding. (ACOG)'),
    (v_topic_id, '239: Which of the following is a "Soft Marker" for Down Syndrome on a 2nd-trimester ultrasound?', '["Echogenic intracardiac focus", "Shortened long bones (femur/humerus)", "Echogenic bowel", "All of the above"]', 3, 'If seen, further screening/diagnostic testing is offered. (Williams)'),
    (v_topic_id, '240: "Absent Nasal Bone" on 1st-trimester ultrasound is associated with:', '["Trisomy 18", "Trisomy 21", "Normal variant", "Cleft palate"]', 1, 'A marker used in the combined screen. (Beckmann)'),
    (v_topic_id, '241: What is the "1-hour Glucose Challenge Test" threshold for a positive screen?', '["100 mg/dL", "130-140 mg/dL", "180 mg/dL", "200 mg/dL"]', 1, 'Threshold varies by institution (130 or 140). (ACOG)'),
    (v_topic_id, '242: A woman has a 1-hour GCT of 150 mg/dL. What is the next step?', '["Diagnose GDM and start insulin", "Perform a 3-hour 100g oral glucose tolerance test", "Repeat the 1-hour test in 2 weeks", "Restrict carbs only"]', 1, 'The 3-hour test is the diagnostic gold standard. (Williams)'),
    (v_topic_id, '243: In the "3-hour GTT," how many abnormal values are required to diagnose GDM?', '["One", "Two or more", "All four", "None"]', 1, 'Fasting, 1-hour, 2-hour, and 3-hour values are measured. (ACOG)'),
    (v_topic_id, '244: What is the fasting glucose goal for a woman with gestational diabetes?', '["< 70 mg/dL", "< 95 mg/dL", "< 120 mg/dL", "< 140 mg/dL"]', 1, 'Postprandial goals are < 140 (1h) or < 120 (2h). (ACOG)'),
    (v_topic_id, '245: Which of the following is a potential neonatal complication of maternal GDM?', '["Neonatal hypoglycemia", "Hypocalcemia", "Hyperbilirubinemia", "All of the above"]', 3, 'Includes respiratory distress syndrome and polycythemia. (Gabbe)'),
    (v_topic_id, '246: "Macrosomia" is a birth weight > 4000-4500g. What is the primary concern during vaginal delivery?', '["Prolonged first stage", "Shoulder dystocia", "Fetal distress", "Uterine rupture"]', 1, 'May require maneuvers like McRoberts or suprapubic pressure. (Beckmann)'),
    (v_topic_id, '247: "Chronic Hypertension with Superimposed Pre-eclampsia" is diagnosed when:', '["Proteinuria develops after 20 weeks in a woman with chronic HTN", "BP becomes suddenly harder to control", "Severe features (e.g., low platelets) develop", "All of the above"]', 3, 'Requires closer monitoring than chronic HTN alone. (ACOG)'),
    (v_topic_id, '248: "Methyldopa" is an antihypertensive drug class:', '["Beta-blocker", "Alpha-2 agonist (centrally acting)", "Calcium channel blocker", "ACE inhibitor"]', 1, 'Traditionally used in pregnancy, though Labetalol is now more common. (Williams)'),
    (v_topic_id, '249: Why is "Magnesium Sulfate" used in pre-eclampsia?', '["To lower blood pressure", "To prevent eclamptic seizures", "To induce labor", "To treat proteinuria"]', 1, 'It is NOT an antihypertensive. (ACOG)'),
    (v_topic_id, '250: What is the most common cause of "maternal death" related to eclampsia?', '["Renal failure", "Liver rupture", "Intracerebral hemorrhage", "Infection"]', 2, 'Due to severe hypertension and vascular damage. (Gabbe)'),
    (v_topic_id, '251: A woman at 38 weeks gestation has "isolated" proteinuria without hypertension. This is:', '["Pre-eclampsia", "Normal finding", "Requires further evaluation (could be renal disease or emerging pre-eclampsia)", "Urinary tract infection"]', 2, 'Must rule out infection and monitor for HTN. (Beckmann)'),
    (v_topic_id, '252: "Placenta Previa" is most commonly diagnosed by:', '["Physical exam", "Transvaginal Ultrasound", "CT scan", "MRI"]', 1, 'TVUS is safe and highly accurate for placental localization. (ACOG)'),
    (v_topic_id, '253: Which of the following is a risk factor for "Placenta Previa"?', '["Prior Cesarean section", "Smoking", "Multiparity", "All of the above"]', 3, 'Also includes multiple gestations and prior uterine surgery. (Williams)'),
    (v_topic_id, '254: What is the standard mode of delivery for a "Complete Placenta Previa"?', '["Vaginal delivery", "Induction of labor", "Scheduled Cesarean section (usually at 36-37 weeks)", "Vacuum extraction"]', 2, 'Vaginal delivery is impossible and dangerous. (ACOG)'),
    (v_topic_id, '255: A "Sinusoidal" fetal heart rate pattern is often seen in:', '["Fetal hypoxia", "Severe fetal anemia (e.g., from vasa previa or Rh disease)", "Maternal drug use (opioids)", "All of the above"]', 3, 'A wave-like, smooth baseline with no accelerations. (Gabbe)'),
    (v_topic_id, '256: "Vasa Previa" vessels are fetal in origin. If they rupture during ROM, what is the expected result?', '["Massive maternal hemorrhage", "Rapid fetal exsanguination and distress", "Nothing, it''s normal", "Cervical change"]', 1, 'Fetal blood volume is small; even 50-100 mL loss is fatal. (Beckmann)'),
    (v_topic_id, '257: Which of the following is a risk factor for "Uterine Rupture"?', '["Prior Cesarean section (especially classical incision)", "Previous myomectomy", "Excessive oxytocin use", "All of the above"]', 3, 'A surgical emergency. (Williams)'),
    (v_topic_id, '258: What is the classic finding on fetal monitoring during a "Uterine Rupture"?', '["Accelerations", "Abrupt and severe fetal bradycardia", "Early decelerations", "Sinusoidal rhythm"]', 1, 'Often accompanied by loss of fetal station and maternal shock. (ACOG)'),
    (v_topic_id, '259: "Amniotic Fluid Embolism" is a rare, catastrophic event presenting with:', '["Vaginal bleeding", "Sudden cardiovascular collapse, DIC, and respiratory failure during labor", "Fever", "High BP"]', 1, 'High mortality rate; management is supportive. (Gabbe)'),
    (v_topic_id, '260: What is the most common "initial" symptom of placental abruption?', '["Bleeding", "Abdominal pain", "Firm, tender uterus", "Rupture of membranes"]', 1, 'Pain is present in ~80% of cases. (Beckmann)'),
    (v_topic_id, '261: "Occult Abruption" refers to:', '["Small amount of bleeding", "Bleeding that is trapped behind the placenta and not visible vaginally", "Abruption diagnosed after delivery", "None of the above"]', 1, 'Can still cause significant fetal distress and maternal pain. (Williams)'),
    (v_topic_id, '262: In a patient with preterm labor (24-34 weeks), what is the purpose of administering "Corticosteroids" (Betamethasone)?', '["To stop contractions", "To accelerate fetal lung maturity and reduce intracranial hemorrhage", "To treat infection", "To increase maternal blood sugar"]', 1, 'Standard of care for threatened preterm delivery. (ACOG)'),
    (v_topic_id, '263: "Magnesium Sulfate" in the setting of PRETERM labor (not pre-eclampsia) is used for:', '["Seizure prophylaxis", "Fetal neuroprotection (reducing the risk of cerebral palsy)", "Stopping contractions permanently", "Lowering BP"]', 1, 'Given to women at risk of imminent delivery < 32 weeks. (ACOG)'),
    (v_topic_id, '264: Which medication is commonly used as a "Tocolytic" (to temporarily stop labor for steroid administration)?', '["Nifedipine (Calcium channel blocker)", "Indomethacin", "Terbutaline (Beta-agonist)", "All of the above"]', 3, 'Used for 48 hours to allow steroids to work. (Williams)'),
    (v_topic_id, '265: "Indomethacin" (NSAID) as a tocolytic is avoided after 32 weeks because it can cause:', '["Maternal ulcers", "Premature closure of the fetal ductus arteriosus", "Oligohydramnios", "Both B and C"]', 3, 'Also causes reversible decrease in fetal urine output. (Gabbe)'),
    (v_topic_id, '266: What is the definition of "Preterm Premature Rupture of Membranes" (PPROM)?', '["ROM at term", "ROM before 37 weeks WITHOUT contractions/labor", "ROM during labor", "ROM in the 1st trimester"]', 1, 'Requires monitoring for infection and fetal distress. (ACOG)'),
    (v_topic_id, '267: "Latency Antibiotics" (Ampicillin + Erythromycin) are given in PPROM to:', '["Treat chorioamnionitis", "Prolong the interval between ROM and delivery", "Stop contractions", "Prevent GBS only"]', 1, 'Shown to improve neonatal outcomes. (Williams)'),
    (v_topic_id, '268: What is the most common cause of "post-term" pregnancy complications?', '["Fetal macrosomia", "Placental insufficiency and oligohydramnios", "Meconium aspiration syndrome", "All of the above"]', 3, 'Risks increase significantly after 42 weeks. (Gabbe)'),
    (v_topic_id, '269: A "Breech" presentation where both hips and knees are flexed (sitting cross-legged) is called:', '["Frank breech", "Complete breech", "Footling breech", "Incomplete breech"]', 1, 'Frank breech has hips flexed and knees extended (feet near head). (Beckmann)'),
    (v_topic_id, '270: "External Cephalic Version" (ECV) is a procedure used to:', '["Turn a breech fetus to vertex manually", "Measure the pelvis", "Induce labor", "Extract a retained placenta"]', 0, 'Typically attempted after 36-37 weeks if no contraindications. (ACOG)'),
    (v_topic_id, '271: Which of the following is a contraindication to "Vaginal Birth After Cesarean" (VBAC)?', '["Prior low transverse uterine incision", "Prior classical (vertical) uterine incision", "Twins", "Maternal age > 35"]', 1, 'Classical incisions have a high risk of rupture during labor. (ACOG)'),
    (v_topic_id, '272: What is the "10% rule" for maternal blood pressure drop after delivery?', '["BP should drop by 10%", "Normal to drop 10 mmHg", "Not a real rule", "A drop in Hct of 10% defines postpartum hemorrhage"]', 3, 'A common definition of PPH, though clinical estimated blood loss (EBL) is more common. (Williams)'),
    (v_topic_id, '273: What is the estimated blood loss (EBL) threshold for "Postpartum Hemorrhage" after a vaginal delivery?', '["250 mL", "500 mL", "1000 mL", "2000 mL"]', 1, 'Threshold is 1000 mL for C-section (though ACOG recently updated both to 1000 mL). (ACOG)'),
    (v_topic_id, '274: "Active Management of the Third Stage of Labor" (AMTSL) to prevent PPH includes:', '["Uterotonic administration (Oxytocin)", "Controlled cord traction", "Uterine massage", "All of the above"]', 3, 'Significantly reduces the risk of uterine atony. (WHO)'),
    (v_topic_id, '275: "Lochia Serosa" is the pinkish-brown postpartum discharge occurring between:', '["Days 1-3", "Days 4-10", "Days 10-14", "After 1 month"]', 1, 'Follows lochia rubra. (Gabbe)'),
    (v_topic_id, '276: A woman at 6 weeks postpartum has not yet had a period. She is exclusively breastfeeding. This is:', '["Secondary amenorrhea", "Lactational amenorrhea", "Asherman syndrome", "Pregnancy"]', 1, 'Normal due to high prolactin levels suppressing GnRH. (Beckmann)'),
    (v_topic_id, '277: When is the "Postpartum Checkup" typically scheduled?', '["1 week", "2 weeks", "4-6 weeks", "3 months"]', 2, 'To assess physical and emotional recovery, contraception, and breastfeeding. (ACOG)'),
    (v_topic_id, '278: What is the primary cause of "Neonatal Sepsis" in infants born to GBS-positive mothers who did not receive prophylaxis?', '["E. coli", "Group B Streptococcus (Streptococcus agalactiae)", "Listeria", "Staph aureus"]', 1, 'Presents as respiratory distress, pneumonia, or meningitis. (Williams)'),
    (v_topic_id, '279: Which of the following is an "Indication" for GBS prophylaxis during labor if the mother''s status is unknown?', '["Preterm delivery (< 37 weeks)", "ROM >= 18 hours", "Maternal fever (> 100.4F)", "All of the above"]', 3, 'Also includes a previous infant with GBS disease or GBS bacteriuria in current pregnancy. (ACOG)'),
    (v_topic_id, '280: The first-line antibiotic for GBS prophylaxis in labor is:', '["Clindamycin", "Penicillin G (or Ampicillin)", "Vancomycin", "Ceftriaxone"]', 1, 'Given as a loading dose and then every 4 hours until delivery. (CDC)'),
    (v_topic_id, '281: Which maternal infection is associated with "hydrops fetalis" in the second trimester?', '["HIV", "Parvovirus B19", "Toxoplasmosis", "Rubella"]', 1, 'Fetal anemia leads to heart failure and hydrops. (Gabbe)'),
    (v_topic_id, '282: "TORCH" infections stand for:', '["Toxo, Other (Syphilis, Parvo, Varicella), Rubella, CMV, HSV", "Tetanus, Organs, Respiratory, Cardiac, Hematology", "None of the above", "All of the above"]', 0, 'A group of infections that can cross the placenta. (Beckmann)'),
    (v_topic_id, '283: "Congenital Rubella" is most likely to cause defects if the infection occurs in the:', '["First trimester", "Second trimester", "Third trimester", "During labor"]', 0, 'Risk of defects is up to 80% if infected < 12 weeks. (Williams)'),
    (v_topic_id, '284: Which TORCH infection is associated with "intracranial calcifications" and "chorioretinitis"?', '["CMV", "Toxoplasmosis", "Both", "Neither"]', 2, 'Characteristic findings for both, though distribution of calcifications differs. (Gabbe)'),
    (v_topic_id, '285: A pregnant woman at 32 weeks has "Genital Herpes" (HSV-2) lesions. What is the recommended management for delivery?', '["Vaginal delivery is safe", "Cesarean section if active lesions or prodromal symptoms are present at the time of labor", "C-section for all patients with a history of HSV", "Induction at 37 weeks"]', 1, 'To prevent vertical transmission and neonatal HSV. (ACOG)'),
    (v_topic_id, '286: What medication is routinely given to women with a history of HSV starting at 36 weeks?', '["Acyclovir or Valacyclovir suppression", "Topical creams", "IVIG", "None"]', 0, 'Reduces the risk of active lesions at delivery and the need for C-section. (ACOG)'),
    (v_topic_id, '287: "Vertical Transmission" of HIV can be reduced to < 1% with:', '["Antiretroviral therapy (ART) during pregnancy", "IV Zidovudine during labor", "Neonatal ART and avoidance of breastfeeding", "All of the above"]', 3, 'Highly successful with modern management. (ACOG)'),
    (v_topic_id, '288: Which of the following is a contraindication to "breastfeeding" in the developed world?', '["HIV", "Hepatitis B", "Hepatitis C", "Common cold"]', 0, 'Formula is a safe and preferred alternative to prevent transmission. (WHO/CDC)'),
    (v_topic_id, '289: What is the primary concern with "Hepatitis B" in the neonate?', '["Acute liver failure", "90% risk of chronic infection and future cirrhosis/cancer if not treated at birth", "Neonatal jaundice only", "None"]', 1, 'Neonates have a high rate of chronicity. (Williams)'),
    (v_topic_id, '290: A woman has "Gestational Hypertension" at 38 weeks. What is the management?', '["Expectant management until 41 weeks", "Induction of labor", "Strict bed rest", "C-section"]', 1, 'Delivery is indicated at 37 weeks for gestational hypertension and pre-eclampsia without severe features. (ACOG)'),
    (v_topic_id, '291: "Labor Augmentation" differs from "Induction" in that:', '["Augmentation is for women already in labor but with inadequate contractions", "Induction starts labor from scratch", "Both use Oxytocin", "All of the above"]', 3, 'Used to correct "arrest of progress." (Beckmann)'),
    (v_topic_id, '292: What is the most common reason for an "Inadequate Bishop Score"?', '["Fetal size", "Unripe (firm, long, posterior) cervix", "Patient age", "Previous C-section"]', 1, 'Cervical ripening agents (e.g., Misoprostol) are used to improve the score. (Williams)'),
    (v_topic_id, '293: Which of the following is a "Cervical Ripening" agent?', '["Oxytocin", "Prostaglandin E2 (Dinoprostone) or PGE1 (Misoprostol)", "Magnesium Sulfate", "Terbutaline"]', 1, 'Helps soften and thin the cervix. (ACOG)'),
    (v_topic_id, '294: "Tachysystole" (too many contractions) during induction is defined as:', '["More than 3 contractions in 10 minutes", "More than 5 contractions in 10 minutes (averaged over 30 min)", "Contractions lasting > 2 minutes", "None of the above"]', 1, 'Can lead to fetal distress due to inadequate rest periods. (ACOG)'),
    (v_topic_id, '295: The "Station" of the fetal head refers to its relationship to the:', '["Symphysis pubis", "Ischial spines", "Sacral promontory", "Perineum"]', 1, 'Station 0 is at the level of the spines. (Beckmann)'),
    (v_topic_id, '296: "Negative Station" (-1, -2, -3) means the head is:', '["Below the ischial spines", "Above the ischial spines", "In the vagina", "At the spines"]', 1, 'Head is still high in the pelvis. (Williams)'),
    (v_topic_id, '297: A "C-section" for a fetus in a "Transverse Lie" is:', '["Elective", "Mandatory (cannot be delivered vaginally)", "Only if they are large", "Not necessary"]', 1, 'Vaginal delivery of a transverse lie is impossible. (Gabbe)'),
